<?php

declare(strict_types=1);

namespace Drupal\Tests\my_module\FunctionalJavascript;

use Drupal\FunctionalJavascriptTests\WebDriverTestBase;
use PHPUnit\Framework\Attributes\Group;
use PHPUnit\Framework\Attributes\RunTestsInSeparateProcesses;

/**
 * Tests the 'Show advanced' reveal on the my_module settings form.
 */
#[Group('my_module')]
#[RunTestsInSeparateProcesses]
class AdvancedSettingsRevealTest extends WebDriverTestBase {

  /**
   * {@inheritdoc}
   */
  protected static $modules = ['my_module'];

  /**
   * {@inheritdoc}
   */
  protected $defaultTheme = 'stark';

  /**
   * {@inheritdoc}
   */
  protected function setUp(): void {
    parent::setUp();

    $this->drupalLogin($this->drupalCreateUser(['administer my_module']));
  }

  /**
   * Tests that the advanced fieldset is hidden until the checkbox is checked.
   */
  public function testAdvancedFieldsetToggles(): void {
    $this->drupalGet('/admin/config/system/my-module');
    $page = $this->getSession()->getPage();

    // With #states the wrapper is already in the DOM, just hidden. Assert on
    // visibility, not presence: waitForElement() would match immediately and
    // pass even if the reveal behaviour were completely broken.
    $wrapper = $page->find('css', '#edit-advanced-wrapper');
    $this->assertNotNull($wrapper, 'The advanced fieldset is rendered.');
    $this->assertFalse($wrapper->isVisible(), 'The advanced fieldset starts hidden.');

    $page->checkField('show_advanced');

    $this->assertNotEmpty(
      $this->assertSession()->waitForElementVisible('css', '#edit-advanced-wrapper'),
      'The advanced fieldset becomes visible after checking "Show advanced".'
    );

    // Unchecking hides it again. There is no waitForElementHidden(), and the
    // element is hidden rather than removed, so poll the DOM directly.
    $page->uncheckField('show_advanced');
    $this->assertJsCondition(
      'document.querySelector("#edit-advanced-wrapper").offsetParent === null'
    );
    $this->assertFalse($wrapper->isVisible(), 'The advanced fieldset is hidden again.');
  }

  /**
   * Tests that a value entered in the revealed fieldset is submitted.
   */
  public function testRevealedFieldIsSubmitted(): void {
    $this->drupalGet('/admin/config/system/my-module');
    $page = $this->getSession()->getPage();

    $page->checkField('show_advanced');
    $this->assertNotEmpty(
      $this->assertSession()->waitForElementVisible('css', '#edit-advanced-wrapper')
    );

    $page->fillField('advanced_threshold', '42');
    $page->pressButton('Save configuration');

    $this->assertSession()->pageTextContains('The configuration options have been saved.');
    $this->assertSame(
      42,
      $this->config('my_module.settings')->get('advanced_threshold')
    );
  }

}
```

**Assumptions to adjust for your module:** module name `my_module`, route `/admin/config/system/my-module`, permission `administer my_module`, checkbox `#name` of `show_advanced`, and the field `advanced_threshold` inside the fieldset. The `#[Group]` attribute needs PHPUnit 10+ (Drupal 11.2+); on 10.x use the `@group my_module` docblock annotation instead.

**If the reveal is AJAX rather than `#states`** the wrapper genuinely does not exist on initial load, so the first block changes to:

```php
$this->assertSession()->elementNotExists('css', '#edit-advanced-wrapper');
$page->checkField('show_advanced');
$this->assertSession()->assertWaitOnAjaxRequest();
$this->assertNotEmpty(
  $this->assertSession()->waitForElement('css', '#edit-advanced-wrapper')
);
```

